/** Optional customer note stays in the private enquiry, never in AI context. */
function rm_mortii_customer_message($value): string {
    if(!is_string($value)||strlen($value)>8000||preg_match('//u',$value)!==1
        ||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/',$value))throw new InvalidArgumentException('Wiadomość może mieć maksymalnie 2000 znaków.');
    $value=trim(str_replace(["\r\n","\r"],"\n",$value));
    if(preg_match_all('/./us',$value)>2000)throw new InvalidArgumentException('Wiadomość może mieć maksymalnie 2000 znaków.');
    return $value;
}
